    border-color:rgba(224,122,139,.9);
    box-shadow:
        0 14px 26px -14px rgba(194,90,114,.7),
        0 0 0 1px rgba(224,122,139,.35) inset;
}
.src-card.selected .src-name{color:var(--rose-dark);font-weight:700}

.all-card{
    background:linear-gradient(160deg, #fff7ea, #fdeccb);
    border-color:rgba(243,207,139,.65);
}
.all-card .card-ico{
    font-size:11px;
    color:var(--gold);
    transition:all .3s;
}
.all-card:hover{
    border-color:rgba(201,165,92,.9);
    background:linear-gradient(160deg,#fff9f0,#fbe4b8);
}
.all-card.selected{
    background:linear-gradient(145deg,#fde7b8,#f3c97a);
    border-color:rgba(201,165,92,.9);
    box-shadow:
        0 14px 26px -14px rgba(180,140,70,.7),
        0 0 0 1px rgba(201,165,92,.35) inset;
}
.all-card.selected .src-name{color:#7a5a1c}
.all-card.selected .card-ico{
    color:#7a5a1c;
    transform:rotate(72deg) scale(1.15);
}

.vip-tag{
    position:absolute;bottom:5px;right:6px;
    display:inline-flex;align-items:center;justify-content:center;
    font-size:8px;font-weight:800;
    padding:1px 5px;
    border-radius:6px;
    color:#8a6420;
    background:rgba(243,207,139,.55);
    border:1px solid rgba(201,165,92,.55);
    letter-spacing:.3px;
    line-height:1.2;
}

.foot{padding:20px 22px 24px}

.clear-btn{
    display:flex;align-items:center;justify-content:center;gap:8px;
    width:100%;
    padding:12px;
    border-radius:14px;
    border:1px dashed rgba(224,122,139,.45);
    background:linear-gradient(135deg, rgba(255,255,255,.7), rgba(255,236,240,.4));
    color:var(--rose);
    font-family:inherit;
    font-size:12.5px;
    font-weight:600;
    letter-spacing:1px;
    cursor:pointer;
    transition:all .28s;
    box-shadow:0 1px 0 rgba(255,255,255,.9) inset;
}
.clear-btn i{font-size:12px;transition:transform .4s}
.clear-btn:hover{
    border-color:rgba(224,122,139,.9);
    background:linear-gradient(135deg,#fff,#ffeef2);
    color:var(--rose-dark);
}
.clear-btn:hover i{transform:rotate(-180deg)}
.clear-btn:active{transform:scale(.985)}

@media (max-width:400px){
