    </svg>`;

    let encodedSvg = java.base64Encode(svg);

    let jsFunction = 'showQDCmt';
    let date = String(Date.now()).match(/(\d{6}$)/)[1];

    const baseData = `data:image/svg+xml;base64,${encodedSvg},{'${isModifiedVersion ? 'click' : 'js'}':'${jsFunction}("${bid}","${cid}","${paraId}","${date}")','style':'full'}`;

