function buildSearchResult(key, sourceParam, host) {
    let { java } = this;

    let fanqieMatch = null;
    if (key && typeof key === 'string') {
        fanqieMatch = key.match(/^(\d{19})@?(番茄小说|番茄听书|番茄漫画|番茄畅听|番茄短剧)?$/);
    }

    if (fanqieMatch) {
        let bookId = fanqieMatch[1];
        let inlineSource = fanqieMatch[2] || '';
        return handleFanqieSearch.call(this, bookId, host, inlineSource);
    } else if (key && key.length == 19 && !Number.isNaN(parseInt(key))) {
        return handleFanqieSearch.call(this, key, host, '');
    } else if (key && (key.length == 6 || key.length == 7 || key.length == 8) && !Number.isNaN(parseInt(key))) {
        return handleJjwxcSearch.call(this, key, host);
    } else {
        return host + '/search?login=search&key={{encodeURIComponent(key)}}&page={{page}}' + sourceParam;
