function loginqt() {
    let base_url = String(getArgument('server') || '').replace(/\/+$/, '');
    let ck = String(cookie.getKey(base_url, "qttoken"));
    if (!ck) {
        java.longToast('\n\n🚫请先登录!')
        return;
    }

    // 阅读器与网页使用不同 Cookie 容器，先换取一次性交接码再打开网页。
    try {
        let deviceId = String(cookie.getKey(base_url, "deviceId") || '');
        let options = JSON.stringify({
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({qttoken: ck, deviceId: deviceId})
        });
        let response = JSON.parse(java.ajax(base_url + '/source_login_handoff,' + options));
        if (response && response.code == 0 && response.handoff) {
            let handoffUrl = base_url + '/source_login_handoff?code=' + encodeURIComponent(response.handoff);
            java.startBrowserAwait(handoffUrl, '大灰狼小说后台');
        } else {
            java.longToast('\n\n🚫登录状态已失效，请重新登录!');
        }
    } catch (e) {
        java.log('用户后台登录交接失败: ' + e);
        java.longToast('\n\n🚫暂时无法打开用户后台，请稍后重试!');
    }
}


