// 远程设置页面仅负责界面，用户配置仍保存在当前阅读软件的源变量中。
function openSourceSettings() {
    var current = {};
    try {
        current = JSON.parse(String(source.getVariable() || '{}'));
    } catch (e) {}

    if (!current || typeof current !== 'object') current = {};
    if (!current.server) current.server = getArgument('server') || host[0];
    if (!current.shuqi_tone_id || current.shuqi_tone_id === '默认音色') {
        current.shuqi_tone_id = 'multi_role';
    }
    current.pstyle = String(current.pstyle || '0');

    var settingsNonce = String(new Date().getTime()) + '_' + String(Math.floor(Math.random() * 1000000));
    current._settings_nonce = settingsNonce;
    var initialSettingsJson = JSON.stringify(current);

    var baseUrl = String(current.server || host[0]).replace(/\/+$/, '');
    var settingsUrl = baseUrl + '/source-settings#config=' + encodeURIComponent(JSON.stringify(current));
    var browserResult;
    var body = '';

    try {
        var settingsPage = String(java.ajax(baseUrl + '/source-settings?_=' + String(new Date().getTime())) || '');
        var stateMarker = 'let state = parseInitialState();';
        if (settingsPage.indexOf(stateMarker) < 0) throw new Error('设置页面版本不兼容');

        var injectedState = 'let state = { ...defaults, ...JSON.parse(decodeURIComponent("' +
            encodeURIComponent(JSON.stringify(current)) + '")) };';
        settingsPage = settingsPage.replace(stateMarker, injectedState);

        var relativeProbe = String.fromCharCode(96) + '$' + '{location.pathname}?probe=';
        var absoluteProbe = String.fromCharCode(96) + baseUrl + '/source-settings?probe=';
        settingsPage = settingsPage.replace(relativeProbe, absoluteProbe);
        var openUrl = 'data:text/html;base64,' + java.base64Encode(settingsPage);
        browserResult = java.startBrowserAwait(openUrl, '书源设置', false);

        body = browserResult && typeof browserResult.body === 'function'
            ? String(browserResult.body())
            : (browserResult && browserResult.body != null ? String(browserResult.body) : String(browserResult || ''));
    } catch (e) {
        java.longToast('\n当前阅读版本无法打开设置中心，原登录页设置仍可使用。\n' + e);
        return;
    }

    function decodeSafe(value) {
        try {
            return decodeURIComponent(String(value || '').trim());
        } catch (e) {
            return String(value || '').trim();
        }
    }

    function parseCookieString(cookieStr) {
        var output = {};
        cookieStr = String(cookieStr || '');
        if (!cookieStr || cookieStr == 'null' || cookieStr == 'undefined') return output;
        var pairs = cookieStr.split(';');
        for (var i = 0; i < pairs.length; i++) {
            var pair = pairs[i];
            var index = pair.indexOf('=');
            if (index < 0) continue;
            var key = decodeSafe(pair.substring(0, index));
            var value = decodeSafe(pair.substring(index + 1));
            output[key] = value;
        }
        return output;
    }

    function readSettingsResultFromBody(pageBody) {
        var match = String(pageBody || '').match(/<script\b[^>]*\bid=["']source-settings-(?:final-)?result["'][^>]*>([\s\S]*?)<\/script>/i);
        if (!match || !match[1]) return null;
        var raw = decodeSafe(match[1]);
        if (!raw) return null;
        return JSON.parse(raw);
    }

    function readSettingsResultFromUrl(result) {
        var candidates = [];
        try { candidates.push(String(result || '')); } catch (e) {}
        try {
            if (result && typeof result.url === 'function') candidates.push(String(result.url() || ''));
            else if (result && result.url != null) candidates.push(String(result.url));
        } catch (e) {}
        try {
            if (result && typeof result.getUrl === 'function') candidates.push(String(result.getUrl() || ''));
        } catch (e) {}

        for (var i = 0; i < candidates.length; i++) {
            var match = candidates[i].match(/(?:#config=|[?&](?:config|source_settings_result)=)([^\s"'<>]+)/i);
            if (!match || !match[1]) continue;
            try {
                var parsed = JSON.parse(decodeSafe(match[1]));
                if (parsed && typeof parsed === 'object') return parsed;
            } catch (e) {}
        }
        return null;
    }

    function readSettingsResultFromCookie(hostUrl) {
        var urls = [hostUrl, hostUrl + '/', settingsUrl];
        var seen = {};
        for (var u = 0; u < urls.length; u++) {
            var target = String(urls[u] || '');
            if (!target || seen[target]) continue;
            seen[target] = true;
            var cookieStr = '';
            try {
                cookieStr = String(cookie.getCookie(target) || '');
            } catch (e) {}
            var cookieData = parseCookieString(cookieStr);
            if (cookieData.source_settings_result) {
                return JSON.parse(cookieData.source_settings_result);
            }
        }
        return null;
    }


    function readBubbleResultFromCookie(hostUrl) {
        var urls = [hostUrl, hostUrl + '/', hostUrl + '/static/bubble_preview.html'];
        for (var urlIndex = 0; urlIndex < urls.length; urlIndex++) {
            var cookieString = '';
            try {
                cookieString = String(cookie.getCookie(urls[urlIndex]) || '');
            } catch (e) {}
            var cookieData = parseCookieString(cookieString);
            if (!cookieData.bubble_settings_result) continue;
            try {
                var parsed = JSON.parse(cookieData.bubble_settings_result);
                if (parsed && typeof parsed === 'object') return parsed;
            } catch (e) {}
        }
        return null;
    }

    try {
        var resultType = '';
        var next = readSettingsResultFromBody(body);
        if (next) resultType = '内嵌页面';
        if (!next) {
            next = readSettingsResultFromCookie(baseUrl);
            if (next) resultType = 'Cookie';
        }
        if (!next) {
            next = readSettingsResultFromUrl(browserResult);
            if (next) resultType = 'URL';
        }
        if (!next || typeof next !== 'object') throw new Error('未读取到设置结果');
        if (String(next._settings_nonce || '') !== settingsNonce) throw new Error('设置结果未更新');

        var bubbleHosts = [String(next.server || baseUrl).replace(/\/+$/, ''), baseUrl].concat(host || []);
        var checkedBubbleHosts = {};
        for (var bubbleHostIndex = 0; bubbleHostIndex < bubbleHosts.length; bubbleHostIndex++) {
            var bubbleHost = String(bubbleHosts[bubbleHostIndex] || '').replace(/\/+$/, '');
            if (!bubbleHost || checkedBubbleHosts[bubbleHost]) continue;
            checkedBubbleHosts[bubbleHost] = true;
            var bubbleResult = readBubbleResultFromCookie(bubbleHost);
            if (!bubbleResult) continue;
            if (String(bubbleResult._bubble_nonce || '') !== settingsNonce) continue;
            if (String(bubbleResult._bubble_applied || '') !== '1') continue;
            var bubbleStyle = String(bubbleResult.pstyle || '');
            if (/^[A-Za-z0-9_-]{1,32}$/.test(bubbleStyle)) next.pstyle = bubbleStyle;
            break;
        }
        if (resultType === 'URL' && JSON.stringify(next) === initialSettingsJson) {
            throw new Error('源阅仅返回了初始地址，未返回修改后的设置');
        }
        delete next._settings_nonce;
        if (!next.server) next.server = baseUrl;
        if (!next.shuqi_tone_id || next.shuqi_tone_id === '默认音色') next.shuqi_tone_id = 'multi_role';
        next.pstyle = String(next.pstyle || '0');
        source.setVariable(JSON.stringify(next));
        try { java.log('书源设置回传方式：' + resultType); } catch (ignore) {}
        java.longToast('\n模式：' + (next.tab || '') + '\n来源：' + (next.sources || '') + '\n搜索、发现页或正文刷新后生效。');
    } catch (e) {
        java.longToast('\n未读取到设置结果，已保留原配置。\n' + e);
    }
}

