    var reg = new RegExp(name + '=\"([^\"]*)\"');
    var match = String(noteTag || '').match(reg);
    if (!match) return '';
    try { return decodeFanqieNoteText(match[1]); } catch (e) { return match[1]; }
}

function cleanFanqieGodNoteText(value) {
    var text = String(value || '')
        .replace(/<[^>]*>/g, ' ')
        .replace(/\[fn=(\d+)\]/g, '[表情]')
        .replace(/\s+/g, ' ')
        .trim();
    return text;
}

